CREATE TABLE public.servicehub_replies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL REFERENCES public.servicehub_requests(id), admin_id uuid NOT NULL, channel text NOT NULL CHECK(channel IN ('email','whatsapp')), message text NOT NULL CHECK(char_length(message) BETWEEN 10 AND 2000), delivery_status text NOT NULL DEFAULT 'pending', created_at timestamptz NOT NULL DEFAULT now()); GRANT ALL ON public.servicehub_replies TO service_role; ALTER TABLE public.servicehub_replies ENABLE ROW LEVEL SECURITY; CREATE INDEX servicehub_replies_request_idx ON public.servicehub_replies(request_id, created_at);